            extcodecopy(instance, add(result, 0x20), 0x2d, argsLen)
        }
    }

    /**
     * @notice Constructs bytecode for a clone contract with immutable arguments.
     *
     * This function generates calldata for deploying a minimal proxy contract that
     * delegates calls to an implementation address while embedding immutable arguments.
     *
     * @param implementation The address of the contract to delegate calls to
     * @param args The immutable arguments to embed in the cloned contract
     * @return The constructed bytecode for the clone contract
     */
    function _cloneCodeWithImmutableArgs(address implementation, bytes memory args) private pure returns (bytes memory) {
        // Max args length is 24531 bytes (0x5FD3)
        if (args.length > 24531) {
            revert();
        }
        // The bytecode structure:
        // PUSH2 <total length>
        // DUP1
        // PUSH2 <args start offset>
        // PUSH20 <implementation>
        // ADDRESS
        // PUSH1 0x2d
        // RETURNDATASIZE
        // RETURNDATASIZE
        // CALLDATASIZE
        // PUSH2 <args length>
        // DUP1
        // RETURNDATASIZE
        // RETURNDATASIZE
        // RETURNDATASIZE
        // CALLDATACOPY
        // CALLDATASIZE
        // RETURNDATASIZE
        // RETURNDATASIZE
        // RETURNDATASIZE
        // DELEGATECALL
        // RETURNDATASIZE
        // RETURN

        uint256 argsLen = args.length;
        uint256 totalLen = 0x2d + argsLen;
        bytes memory code = new bytes(totalLen + 0x20);

        assembly ("memory-safe") {
            let ptr := add(code, 0x20)

            // PUSH2 <total length>
            mstore8(ptr, 0x61)
            mstore8(add(ptr, 0x01), shr(8, totalLen))
            mstore8(add(ptr, 0x02), and(totalLen, 0xff))

            // DUP1 + PUSH2 <args start offset = 0x2d>
            mstore8(add(ptr, 0x03), 0x80)
            mstore8(add(ptr, 0x04), 0x61)
            mstore8(add(ptr, 0x05), 0x00)
            mstore8(add(ptr, 0x06), 0x2d)

            // PUSH20 implementation
            mstore8(add(ptr, 0x07), 0x73)
            mstore(add(ptr, 0x08), and(implementation, 0xffffffffffffffffffffffffffffffffffffffff))
            // Clear overflow bytes
            mstore(add(ptr, 0x1c), 0)

            // ADDRESS
            mstore8(add(ptr, 0x1c), 0x30)

            // PUSH1 0x2d
            mstore8(add(ptr, 0x1d), 0x60)
            mstore8(add(ptr, 0x1e), 0x2d)

            // RETURNDATASIZE
            mstore8(add(ptr, 0x1f), 0x3d)

            // RETURNDATASIZE
            mstore8(add(ptr, 0x20), 0x3d)

            // CALLDATASIZE
            mstore8(add(ptr, 0x21), 0x36)

            // PUSH2 <args length>
            mstore8(add(ptr, 0x22), 0x61)
            mstore8(add(ptr, 0x23), shr(8, argsLen))
            mstore8(add(ptr, 0x24), and(argsLen, 0xff))

            // DUP1
            mstore8(add(ptr, 0x25), 0x80)

            // RETURNDATASIZE
            mstore8(add(ptr, 0x26), 0x3d)

            // RETURNDATASIZE
            mstore8(add(ptr, 0x27), 0x3d)

            // RETURNDATASIZE
            mstore8(add(ptr, 0x28), 0x3d)

            // CALLDATACOPY
            mstore8(add(ptr, 0x29), 0x37)

            // CALLDATASIZE
            mstore8(add(ptr, 0x2a), 0x36)

            // RETURNDATASIZE
            mstore8(add(ptr, 0x2b), 0x3d)

            // RETURNDATASIZE
            mstore8(add(ptr, 0x2c), 0x3d)

            // RETURNDATASIZE
            mstore8(add(ptr, 0x2d), 0x3d)

            // DELEGATECALL
            mstore8(add(ptr, 0x2e), 0xf4)

            // RETURNDATASIZE
            mstore8(add(ptr, 0x2f), 0x3d)

            // Copy immutable args into code
            let argsPtr := add(args, 0x20)
            for { let i := 0 } lt(i, argsLen) { i := add(i, 0x20) } {
                mstore(add(add(ptr, 0x30), i), mload(add(argsPtr, i)))
            }
        }
        return code;
    }
}
